package dev.hybridlabs.fishnships.entityimport dev.hybridlabs.fishnships.CommonClassimport dev.hybridlabs.fishnships.entity.ship.CanoeEntityimport dev.hybridlabs.fishnships.entity.ship.CanoeWithChestEntityimport dev.hybridlabs.fishnships.entity.ship.CanoeWithDoubleChestEntityimport dev.hybridlabs.fishnships.entity.ship.RaftEntityimport dev.hybridlabs.fishnships.entity.ship.ShipEntityimport dev.hybridlabs.fishnships.entity.ship.SupplyRaftEntityimport dev.hybridlabs.fishnships.platform.registration.RegistryObjectimport net.minecraft.world.entity.Entityimport net.minecraft.world.entity.EntityDimensionsimport net.minecraft.world.entity.EntityTypeimport net.minecraft.world.entity.MobCategoryobject FSEntityTypes {    val SHIP = registerMisc(        "ship",        ::ShipEntity,            EntityDimensions.fixed(4.75f, 1.0f),    )    val CANOE = registerMisc(        "canoe",        ::CanoeEntity,            EntityDimensions.fixed(2.5f, 0.5625f),    )    val CANOE_WITH_CHEST = registerMisc(        "canoe_with_chest",        ::CanoeWithChestEntity,            EntityDimensions.fixed(2.5f, 0.5625f),    )    val CANOE_WITH_DOUBLE_CHEST = registerMisc(        "canoe_with_double_chest",        ::CanoeWithDoubleChestEntity,            EntityDimensions.fixed(2.5f, 0.5625f),    )    val RAFT = registerMisc(        "raft",        ::RaftEntity,            EntityDimensions.fixed(2.75f, 0.5625f),    )    val SUPPLY_RAFT = registerMisc(        "supply_raft",        ::SupplyRaftEntity,            EntityDimensions.fixed(2.75f, 0.5625f),    )    //#region Misc Entity Registration    private fun <T : Entity> registerMisc(        id: String,        entityFactory: EntityType.EntityFactory<T>,        dimensions: EntityDimensions,    ): RegistryObject<EntityType<T>> {        return CommonClass.ENTITY_TYPES.register(id) {            EntityType.Builder                .of(entityFactory, MobCategory.MISC)                .sized(dimensions.width, dimensions.height)                .clientTrackingRange(10)                .updateInterval(10)                .build(id)        }    }}